    if (!fp) {
        fprintf(stderr, "Error: Cannot open file %s\n", argv[1]);
        return 1;
    }

    // Read and decrypt each ciphertext
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        uint64_t ciphertext;
        if (sscanf(line, "%lu", &ciphertext) == 1) {
            uint64_t plaintext = decrypt(ciphertext);
            printf("%lu\n", plaintext);
        }
    }

    fclose(fp);
    return 0;
}"}

