#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>

static inline uint8_t g_function(uint8_t a,uint8_t b,uint8_t x){uint8_t t=(a+b+x)&0xFF;return ((t<<2)|(t>>6))&0xFF;}
static uint32_t f_function(uint32_t v){
    uint8_t x[4],y[4];
    for(int i=0;i<4;i++){x[i]=v&0xFF;v>>=8;}
    y[2]=g_function(x[3]^x[2],x[1]^x[0],1);
    y[3]=g_function(x[3],y[2],0);
    y[1]=g_function(x[1]^x[0],y[2],0);
    y[0]=g_function(x[0],y[1],1);
    uint32_t o=0;for(int i=0;i<4;i++)o|=(uint32_t)y[i]<<(8*i);return o;
}
static uint32_t expand(uint32_t k){k&=0xFFFFF;return k^(k<<16)^(k*12345);}
static inline int Q(uint32_t x){return (x>>18)&1;}
static inline int P(uint32_t x){x&=0x01010101u;return __builtin_parity(x);}

#define N 32
uint32_t L0[N],R0[N],b3[N],b4[N];
int np;

int main(){
    FILE*fp=fopen("/app/pairs.txt","r");
    unsigned long long p,c;
    np=0;
    while(fscanf(fp,"%llu %llu",&p,&c)==2){
        uint32_t pl=(p>>32)&0xFFFFFFFF, pr=p&0xFFFFFFFF;
        L0[np]=pl; R0[np]=pl^pr;               // post pre-whiten
        uint32_t ch=(c>>32)&0xFFFFFFFF, cl=c&0xFFFFFFFF;
        b4[np]=ch; b3[np]=cl^ch;               // b4=Chigh, b3=Clow^Chigh
        np++;
    }
    fclose(fp);
    fprintf(stderr,"pairs=%d\n",np);

    // candidate k3 via bottom trail
    uint32_t k3c[4096]; int nk3=0;
    for(uint32_t s=0;s<(1u<<20);s++){
        uint32_t k=expand(s); int cst=-1,ok=1;
        for(int i=0;i<np;i++){
            uint32_t L3=b4[i]^f_function(b3[i]^k);
            int e=Q(L0[i])^P(R0[i])^P(L3)^Q(b3[i]);
            if(cst<0)cst=e; else if(e!=cst){ok=0;break;}
        }
        if(ok){ if(nk3<4096)k3c[nk3++]=s; }
    }
    fprintf(stderr,"k3 candidates=%d\n",nk3);

    // candidate k0 via top trail
    uint32_t k0c[4096]; int nk0=0;
    for(uint32_t s=0;s<(1u<<20);s++){
        uint32_t k=expand(s); int cst=-1,ok=1;
        for(int i=0;i<np;i++){
            uint32_t R1=L0[i]^f_function(R0[i]^k);
            int e=Q(R0[i])^P(R1)^P(b3[i])^Q(b4[i]);
            if(cst<0)cst=e; else if(e!=cst){ok=0;break;}
        }
        if(ok){ if(nk0<4096)k0c[nk0++]=s; }
    }
    fprintf(stderr,"k0 candidates=%d\n",nk0);

    // for each (k0,k3) candidate, brute k1,k2
    for(int a=0;a<nk0;a++) for(int b=0;b<nk3;b++){
        uint32_t K0=expand(k0c[a]),K3=expand(k3c[b]);
        // precompute per pair R1,L1,b2
        uint32_t R1[N],b2[N];
        for(int i=0;i<np;i++){ R1[i]=L0[i]^f_function(R0[i]^K0); b2[i]=b4[i]^f_function(b3[i]^K3); }
        // k1: f(R1^k1)==b2^L1, L1=R0
        long k1=-1;
        for(uint32_t s=0;s<(1u<<20)&&k1<0;s++){uint32_t k=expand(s);int ok=1;
            for(int i=0;i<np;i++){ if(f_function(R1[i]^k)!=(b2[i]^R0[i])){ok=0;break;} }
            if(ok)k1=s;
        }
        if(k1<0)continue;
        // k2: f(b2^k2)==b3^R1
        long k2=-1;
        for(uint32_t s=0;s<(1u<<20)&&k2<0;s++){uint32_t k=expand(s);int ok=1;
            for(int i=0;i<np;i++){ if(f_function(b2[i]^k)!=(b3[i]^R1[i])){ok=0;break;} }
            if(ok)k2=s;
        }
        if(k2<0)continue;
        printf("SEEDS %05x %05lx %05lx %05x\n",k0c[a],(unsigned long)k1,(unsigned long)k2,k3c[b]);
    }
    return 0;
}
